begin;
set local request.jwt.claims='{"aal":"aal2"}';
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000971','revision-owner@example.test'),('00000000-0000-4000-8000-000000000972','revision-other@example.test'),('00000000-0000-4000-8000-000000000973','revision-accounting@example.test');
update public.profiles set role='admin' where id in('00000000-0000-4000-8000-000000000971','00000000-0000-4000-8000-000000000972');
update public.profiles set role='accounting' where id='00000000-0000-4000-8000-000000000973';
create temp table revision_options(data jsonb);
insert into revision_options values('{"revision":"00000000-0000-4000-8000-000000000974","profiles":[{"entity":"customers","sheet_name":"Negozi","header_row":1,"mapping":{"legal_name":0},"options":{}}]}');
create temp table revision_rows(data jsonb);
insert into revision_rows values('[{"entity":"customers","sheet":"Negozi","row_number":2,"raw":{"c0":"Negozio sintetico"},"mapped":{"legal_name":"Negozio sintetico"},"status":"valid","messages":[]}]');
grant select on revision_options,revision_rows to authenticated;
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000971';
select public.start_import_batch('00000000-0000-4000-8000-000000000970','mixed','synthetic.csv',repeat('e',64),100);
insert into storage.objects(bucket_id,name,metadata) values('imports','00000000-0000-4000-8000-000000000970.csv','{"size":100}');
select throws_ok($$select public.configure_import_batch('00000000-0000-4000-8000-000000000970','{}','{}')$$,'23514','REVISION_REQUIRED','generic configuration requires revision guard');
select lives_ok($$select public.configure_import_batch('00000000-0000-4000-8000-000000000970',data,'{}',null) from revision_options$$,'initial generic revision configured');
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000970',data) from revision_rows$$,'40001','CONFIG_CONFLICT','old API cannot stage generic rows without revision');
select lives_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000970',data,'00000000-0000-4000-8000-000000000974') from revision_rows$$,'matching revision stages');
select is((select count(*) from public.import_rows where batch_id='00000000-0000-4000-8000-000000000970'),1::bigint,'row exists');
select throws_ok($$select public.configure_import_batch('00000000-0000-4000-8000-000000000970',data,'{}',null) from revision_options$$,'40001','CONFIG_CONFLICT','stale tab cannot overwrite configuration');
select lives_ok($$select public.configure_import_batch('00000000-0000-4000-8000-000000000970',data,'{}','00000000-0000-4000-8000-000000000974') from revision_options$$,'retry same configuration');
select is((select count(*) from public.import_rows where batch_id='00000000-0000-4000-8000-000000000970'),1::bigint,'retry keeps staging');
select lives_ok($$select public.configure_import_batch('00000000-0000-4000-8000-000000000970',jsonb_set(data,'{revision}','"00000000-0000-4000-8000-000000000975"'),'{}','00000000-0000-4000-8000-000000000974') from revision_options$$,'changed configuration accepted with current revision');
select is((select count(*) from public.import_rows where batch_id='00000000-0000-4000-8000-000000000970'),0::bigint,'old rows removed on configuration change');
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000970',data,'00000000-0000-4000-8000-000000000974') from revision_rows$$,'40001','CONFIG_CONFLICT','in-flight old chunk rejected under SQL lock');
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000970',jsonb_build_array(jsonb_set(data->0,'{sheet}','"Other"')),'00000000-0000-4000-8000-000000000975') from revision_rows$$,'23514','INVALID_PROFILE_ROW','unconfigured sheet cannot be staged');
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000970',jsonb_build_array(jsonb_set(data->0,'{row_number}','1')),'00000000-0000-4000-8000-000000000975') from revision_rows$$,'23514','INVALID_PROFILE_ROW','header cannot be staged');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000972';
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000970',data,'00000000-0000-4000-8000-000000000975') from revision_rows$$,'42501','FORBIDDEN','other admin cannot stage');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000973';
select throws_ok($$select public.stage_import_rows('00000000-0000-4000-8000-000000000970',data,'00000000-0000-4000-8000-000000000975') from revision_rows$$,'42501','FORBIDDEN','accounting cannot stage mixed batch');
select * from finish();rollback;
